import { useId, useState } from 'react'
import './styles.css'

export interface CommandItem {
  value: string
  label: string
  shortcut?: string
  group?: string
}

export interface CommandPaletteProps {
  open: boolean
  onOpenChange?: (open: boolean) => void
  commands: CommandItem[]
  query?: string
  onQueryChange?: (query: string) => void
  onSelect: (value: string) => void
  label: string
  placeholder?: string
  emptyLabel?: string
  closeLabel?: string
  className?: string
}

/**
 * Filters then stably sorts commands for the palette list.
 *
 * @complexity time O(n log n) | space O(n) | n = command count
 * @guarantees default order is localeCompare('en') on label then value — reproducible
 */
export function filterCommands(commands: CommandItem[], query: string): CommandItem[] {
  const needle = query.trim().toLowerCase()
  const matched =
    needle.length === 0
      ? commands
      : commands.filter(
          (command) =>
            command.label.toLowerCase().includes(needle) ||
            command.value.toLowerCase().includes(needle),
        )
  return [...matched].sort((left, right) => {
    const byLabel = left.label.localeCompare(right.label, 'en')
    if (byLabel !== 0) return byLabel
    return left.value.localeCompare(right.value, 'en')
  })
}

export function CommandPalette({
  open,
  onOpenChange,
  commands,
  query,
  onQueryChange,
  onSelect,
  label,
  placeholder = 'Type a command',
  emptyLabel = 'No commands',
  closeLabel = 'Close',
  className,
}: CommandPaletteProps) {
  const listId = useId()
  const [internalQuery, setInternalQuery] = useState('')
  const [activeIndex, setActiveIndex] = useState(0)
  const currentQuery = query ?? internalQuery
  const visible = filterCommands(commands, currentQuery)
  const classes = ['cu-command-palette', className].filter(Boolean).join(' ')
  const aiState = open ? (currentQuery.trim().length > 0 ? 'filtered' : 'open') : 'closed'

  function setQuery(next: string) {
    if (query === undefined) setInternalQuery(next)
    onQueryChange?.(next)
    setActiveIndex(0)
  }

  function selectValue(value: string) {
    onSelect(value)
    onOpenChange?.(false)
  }

  if (!open) {
    return (
      <div
        className={classes}
        data-ai-role="command-palette"
        data-ai-intent="choose-action"
        data-ai-state="closed"
        hidden
      />
    )
  }

  const active = visible[activeIndex]
  const activeId = active ? `${listId}-${active.value}` : undefined

  return (
    <div
      className={classes}
      data-ai-role="command-palette"
      data-ai-intent="choose-action"
      data-ai-state={aiState}
    >
      <div className="cu-command-palette__backdrop" />
      <div className="cu-command-palette__positioner">
        <div
          className="cu-command-palette__content"
          role="dialog"
          aria-modal="true"
          aria-label={label}
        >
          <div className="cu-command-palette__toolbar">
            <label className="cu-command-palette__field">
              <span className="cu-command-palette__field-text">{label}</span>
              <input
                className="cu-command-palette__input"
                type="search"
                role="combobox"
                aria-expanded="true"
                aria-controls={listId}
                aria-activedescendant={activeId}
                aria-autocomplete="list"
                value={currentQuery}
                placeholder={placeholder}
                onChange={(event) => setQuery(event.currentTarget.value)}
                onKeyDown={(event) => {
                  if (event.key === 'ArrowDown') {
                    event.preventDefault()
                    setActiveIndex((index) => (visible.length === 0 ? 0 : (index + 1) % visible.length))
                  } else if (event.key === 'ArrowUp') {
                    event.preventDefault()
                    setActiveIndex((index) =>
                      visible.length === 0 ? 0 : (index - 1 + visible.length) % visible.length,
                    )
                  } else if (event.key === 'Enter') {
                    event.preventDefault()
                    if (active) selectValue(active.value)
                  } else if (event.key === 'Escape') {
                    event.preventDefault()
                    onOpenChange?.(false)
                  }
                }}
              />
            </label>
            <button
              type="button"
              className="cu-command-palette__close"
              aria-label={closeLabel}
              onClick={() => onOpenChange?.(false)}
            >
              ×
            </button>
          </div>
          {visible.length === 0 ? (
            <p className="cu-command-palette__empty">{emptyLabel}</p>
          ) : (
            <ul className="cu-command-palette__list" role="listbox" id={listId}>
              {visible.map((command, index) => (
                <li
                  key={command.value}
                  id={`${listId}-${command.value}`}
                  className={
                    'cu-command-palette__option' +
                    (index === activeIndex ? ' cu-command-palette__option--active' : '')
                  }
                  role="option"
                  aria-selected={index === activeIndex}
                  onClick={() => selectValue(command.value)}
                >
                  <span className="cu-command-palette__option-label">{command.label}</span>
                  {command.shortcut ? (
                    <kbd className="cu-command-palette__shortcut">{command.shortcut}</kbd>
                  ) : null}
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    </div>
  )
}

{
  "schemaVersion": "0.2",
  "slug": "command-palette",
  "name": "CommandPalette",
  "family": "B",
  "status": "experimental",
  "purpose": "Offers a searchable command list (⌘K pattern) with a reproducible default sort.",
  "scenarios": [
    "Jump to a command from the keyboard",
    "Filter actions by name",
    "Run a palette command and dismiss the overlay"
  ],
  "props": {
    "open": {
      "type": "boolean",
      "required": true,
      "description": "Whether the palette overlay is shown."
    },
    "onOpenChange": {
      "type": "event",
      "required": false,
      "description": "Called when the overlay should open or close."
    },
    "commands": {
      "type": "node",
      "required": true,
      "description": "Command entries with value, label, optional shortcut and group."
    },
    "query": {
      "type": "string",
      "required": false,
      "description": "Controlled filter query."
    },
    "onQueryChange": {
      "type": "event",
      "required": false,
      "description": "Called when the filter query changes."
    },
    "onSelect": {
      "type": "event",
      "required": true,
      "description": "Called with the command value when a command is run."
    },
    "label": {
      "type": "string",
      "required": true,
      "description": "Accessible name of the dialog and search field."
    },
    "placeholder": {
      "type": "string",
      "required": false,
      "description": "Search field placeholder."
    },
    "emptyLabel": {
      "type": "string",
      "required": false,
      "description": "Copy shown when the filter matches nothing."
    },
    "closeLabel": {
      "type": "string",
      "required": false,
      "description": "Accessible name of the dismiss control."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "closed",
      "description": "Palette is hidden."
    },
    {
      "name": "open",
      "description": "Palette is shown with an empty query."
    },
    {
      "name": "filtered",
      "description": "Palette is shown with a non-empty query."
    }
  ],
  "composition": {
    "allowedParents": ["app-shell", "page"],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not randomize command order; default sort must be localeCompare en on label then value.",
    "Do not trap the user without Escape or a labelled close control."
  ],
  "a11y": {
    "role": "dialog",
    "keyboard": [
      "ArrowDown and ArrowUp move the active option",
      "Enter runs the active command",
      "Escape dismisses the overlay"
    ],
    "focus": "The search field is a combobox; options are in a listbox with aria-activedescendant.",
    "labeling": "Dialog and field share the accessible name; close has an aria-label.",
    "wcag": ["1.3.1", "2.1.1", "2.4.7", "4.1.2"]
  },
  "responsive": {
    "strategy": "Positioner is the query container. Compact is a bottom sheet; tablet/desktop center a constrained dialog. No viewport size media.",
    "breakpoints": {
      "compact": "Full-width sheet at the block-end.",
      "medium": "Centered 36rem dialog at 48rem container width.",
      "large": "Centered 40rem dialog at 80rem container width."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "command-palette",
    "states": ["closed", "open", "filtered"],
    "intents": ["choose-action", "search-select"]
  }
}

{
  "command-palette": {
    "label": "命令面板",
    "placeholder": "输入命令",
    "empty": "没有命令",
    "close": "关闭"
  }
}

/*
 * Query container: the positioner is viewport-sized (fixed inset 0) and
 * acts as the query container, so the bottom-sheet -> centered palette
 * morph is driven by the container, not a viewport media query.
 * 48rem == breakpoint.tablet, 80rem == breakpoint.desktop
 * (packages/tokens/src/core/breakpoint.json).
 */
.cu-command-palette {
  color: var(--cu-color-fg-default);
}

.cu-command-palette__backdrop {
  position: fixed;
  inset: 0;
  z-index: 30;
  background: color-mix(in srgb, var(--cu-color-background-inverse) 66%, transparent);
}

.cu-command-palette__positioner {
  position: fixed;
  inset: 0;
  z-index: 31;
  display: grid;
  place-items: end center;
  overflow: auto;
  container-type: inline-size;
}

.cu-command-palette__content {
  inline-size: 100%;
  max-block-size: min(90vh, 28rem);
  overflow: auto;
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
  border-start-start-radius: var(--cu-radius-xl, var(--cu-radius-lg));
  border-start-end-radius: var(--cu-radius-xl, var(--cu-radius-lg));
  background: var(
    --cu-color-background-translucent-thick,
    var(--cu-color-background-elevated, var(--cu-color-background-default))
  );
  -webkit-backdrop-filter: saturate(var(--cu-saturate-frost, 1))
    blur(var(--cu-blur-thick, var(--cu-blur-surface, 0px)));
  backdrop-filter: saturate(var(--cu-saturate-frost, 1)) blur(var(--cu-blur-thick, var(--cu-blur-surface, 0px)));
  box-shadow: var(
    --cu-shadow-lg,
    0 28px 80px color-mix(in srgb, var(--cu-color-background-inverse) 32%, transparent)
  );
}

.cu-command-palette__toolbar {
  display: flex;
  align-items: flex-end;
  gap: var(--cu-space-2);
}

.cu-command-palette__field {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: calc(var(--cu-space-1) / 2);
}

.cu-command-palette__field-text {
  font-size: 0.875em;
}

.cu-command-palette__input {
  min-block-size: var(--cu-touch-target-min);
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-2);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: inherit;
  font: inherit;
}

.cu-command-palette__input:focus-visible,
.cu-command-palette__close:focus-visible,
.cu-command-palette__option:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: 3px;
}

.cu-command-palette__close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-inline-size: var(--cu-touch-target-min);
  min-block-size: var(--cu-touch-target-min);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.cu-command-palette__empty {
  margin-block-start: var(--cu-space-3);
}

.cu-command-palette__list {
  list-style: none;
  margin: var(--cu-space-2) 0 0;
  padding: 0;
}

.cu-command-palette__option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--cu-space-2);
  min-block-size: var(--cu-touch-target-min);
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-2);
  border-radius: var(--cu-radius-md);
  cursor: pointer;
}

.cu-command-palette__option--active {
  background: color-mix(in srgb, var(--cu-color-palette-brand) 12%, var(--cu-color-background-default));
}

.cu-command-palette__shortcut {
  font: inherit;
  font-size: 0.75em;
  padding-block: var(--cu-space-1);
  padding-inline: var(--cu-space-1);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-sm);
}

@media (hover: hover) {
  .cu-command-palette__option:hover {
    background: color-mix(in srgb, var(--cu-color-background-default) 92%, var(--cu-color-palette-brand));
  }
}

@container (min-width: 48rem) {
  .cu-command-palette__content {
    align-self: start;
    inline-size: min(100%, 36rem);
    margin-block-start: 4rem;
    border-radius: var(--cu-radius-lg);
  }
}

@container (min-width: 80rem) {
  .cu-command-palette__content {
    inline-size: min(100%, 40rem);
  }
}

@media (prefers-reduced-motion: reduce) {
  .cu-command-palette__backdrop,
  .cu-command-palette__content {
    transition-duration: 0.01ms;
  }
}
